USE hwtires;

CREATE TABLE IF NOT EXISTS `job_order_progress` (
  `id` INT PRIMARY KEY AUTO_INCREMENT,
  `job_order_id` INT NOT NULL,
  `quotation_item_id` INT NULL,
  `task_key` VARCHAR(120) NOT NULL,
  `task_name` VARCHAR(255) NOT NULL,
  `task_type` VARCHAR(30) DEFAULT 'service',
  `quantity` INT DEFAULT 1,
  `is_done` TINYINT(1) NOT NULL DEFAULT 0,
  `completed_at` DATETIME NULL,
  `updated_by` INT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY `uniq_job_progress_task` (`job_order_id`, `task_key`),
  INDEX `idx_job_progress_job` (`job_order_id`),
  INDEX `idx_job_progress_done` (`is_done`),
  CONSTRAINT `fk_seed_job_progress_job` FOREIGN KEY (`job_order_id`) REFERENCES `job_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_seed_job_progress_item` FOREIGN KEY (`quotation_item_id`) REFERENCES `quotation_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_seed_job_progress_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `vehicle_ownership_history` (
  `id` INT PRIMARY KEY AUTO_INCREMENT,
  `vehicle_id` INT NOT NULL,
  `customer_id` INT NOT NULL,
  `owned_from` DATE NULL,
  `owned_until` DATE NULL,
  `is_current` TINYINT(1) NOT NULL DEFAULT 1,
  `transfer_notes` TEXT NULL,
  `created_by` INT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_vehicle_ownership_vehicle` (`vehicle_id`),
  INDEX `idx_vehicle_ownership_customer` (`customer_id`),
  INDEX `idx_vehicle_ownership_current` (`vehicle_id`, `is_current`),
  INDEX `idx_vehicle_ownership_dates` (`owned_from`, `owned_until`),
  CONSTRAINT `fk_seed_vehicle_ownership_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_seed_vehicle_ownership_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_seed_vehicle_ownership_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @sql := (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `job_orders` ADD COLUMN `estimated_duration` VARCHAR(120) NULL AFTER `scheduled_end_time`', 'SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'job_orders' AND COLUMN_NAME = 'estimated_duration');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

